# POST /api/sheets/{sheetId}/people/{personId}/merge — a steward merges the person into another on the
# sheet (intoId): their claims, aliases, patrons and pool memberships go to the other and they leave
# the sheet (see MergePerson). Anyone else, the person themselves, or either of them retired, is refused.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateMerge
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: merge
merge:
  class: net.officefloor.hq.app.person.MergePerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonMerged
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithMerged
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the person to merge into: refused when none is named. */
public class ValidateMerge {
    public void validate(@RequestBody MergeRequest request, Out<MergeRequest> body)
            throws InvalidPersonException {
        if (request == null || request.intoId() == null) {
            throw new InvalidPersonException("No person to merge into");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.person;

/** A merge just made: the person merged and the one they were merged into, for the audit line. */
public record Merge(Person from, Person into) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** A steward merges the person into another on the sheet: the person's claims move to the other
 *  (numbers and dates kept, listed after the other's in the order they were added, each keeping any
 *  figure a statement bound it to), their name and aliases become the other's aliases, their patrons are
 *  added to the other's and whoever named them as patron names the other instead (no repeats, never
 *  themselves), their pool memberships (shares added where the other is a member already) and closed
 *  periods' fixed totals move to the other, their statement count is added to the other's (whose last statement stays theirs, or having none
 *  becomes this person's), and the rest of them (holds, watchers, contact) is dropped with the person. Refused (nothing written) for anyone but a steward, for the
 *  person themselves or someone not on the sheet, and when either of them is retired. */
public class MergePerson {
    public void merge(@RequestParam(name = "by", required = false) String by,
            @Val MergeRequest request, @Val Person person, PersonRepository people,
            ClaimRepository claims, PoolRepository pools, PeriodRepository periods,
            RoleRepository roles, Out<Merge> merged) throws InvalidPersonException {
        String user = by == null ? "" : by;
        String sheetId = person.getSheetId();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new InvalidPersonException("Only a steward can merge people");
        }
        if (request.intoId() == person.getId()) {
            throw new InvalidPersonException("A person cannot be merged into themselves");
        }
        Person into = people.find(sheetId, request.intoId());
        if (into == null) {
            throw new InvalidPersonException("No such person on the sheet: " + request.intoId());
        }
        if (person.isRetired() || into.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        claims.moveAll(sheetId, person.getId(), into.getId());
        pools.moveMembers(sheetId, person.getId(), into.getId());
        periods.moveTotals(sheetId, person.getId(), into.getId());
        people.merge(person, into, user);
        merged.set(new Merge(person, into));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the merge just made (PERSON_MERGED). */
public class RecordPersonMerged {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Merge merge, Audit audit) {
        audit.record("PERSON_MERGED sheet=" + merge.into().getSheetId() + " by=" + (by == null ? "" : by)
                + " from=" + merge.from().getName() + " into=" + merge.into().getName());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** Responds with the person merged into, as they stand now. */
public class RespondWithMerged {
    public void respond(@Val Merge merge, ObjectResponse<Person> response) {
        response.send(merge.into());
    }
}
package net.officefloor.hq.app.person;

/** Body of a merge: the id of the person on the sheet the person is merged into. */
public record MergeRequest(Long intoId) {
}
-- A transfer that merges the arriving person into one already on the sheet joins their name and
-- aliases to that person's, so the same alias (as names are compared) may now appear twice on a
-- person: an alias is no longer unique on the sheet by the store, only as the screens add it.
DROP INDEX person_alias_sheet_key;
CREATE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);

